    correctKey: 'C',
    explanation: '雲粒が雨粒まで成長する過程は二つに大別される。温暖雨過程（衝突・併合過程）は0 °C以上の温暖雲で働き、大きさの異なる水滴の落下速度差により大粒が小粒を捕捉して成長するもので、熱帯や夏の下層雲の降水を担う。もう一つのバーグロン過程（氷晶過程）は、過冷却水滴と氷晶が共存する−10〜−20 °C付近の混合雲で働く。氷面上の飽和水蒸気圧が水面上より低いため、水滴が蒸発しながら水蒸気が氷晶へ移り、氷晶が昇華凝結で急成長する。中緯度の降水の多くはこの氷晶過程を経ており、上空で成長した雪が融けて雨として降る。\n\n【図解】二つの降水過程\n　過程｜働く雲｜成長の仕組み\n　温暖雨過程｜温暖雲（0 °C以上）｜落下速度差による衝突・併合\n　バーグロン過程｜混合雲（−10〜−20 °C）｜氷面の低い飽和水蒸気圧\n　主な地域｜温暖雨は熱帯｜氷晶過程は中緯度\n　⇒ 氷面上の飽和水蒸気圧が水面上より低いことが氷晶成長の駆動力になる\n　⚠ 「バーグロン過程は0 °C以上で起こる」は誤り。過冷却水滴が存在する温度域が必須条件。',
