    question: '傾度風（gradient wind）に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '傾度風は気圧傾度力・コリオリ力・摩擦力の三力がつり合った曲線状の等圧線に沿う風である。', explanation: '傾度風は気圧傾度力・コリオリ力・遠心力の三力がつり合った風。摩擦力は含まない。' },
      { key: 'B', text: '低気圧を回る傾度風（cyclostrophic flow）は地衡風より速く、高気圧を回る傾度風（anticyclostrophic flow）は地衡風より遅い。', explanation: '低気圧の傾度風は遠心力が外向きに加わるため、コリオリ力との合力で地衡風と等しい気圧傾度力を満たすには、地衡風より遅い風速が必要。高気圧は逆に地衡風より速い。' },
      { key: 'C', text: '傾度風は直線的な等圧線に沿って吹く風で、等圧線の曲率の効果を無視したものである。', explanation: '等圧線の曲率を無視した（直線等圧線の場合）ものが地衡風。傾度風は等圧線の曲率（遠心力）を考慮した風である。' },
      { key: 'D', text: '北半球において、低気圧の傾度風の速度は同じ気圧傾度の地衡風の速度より小さい。', explanation: '低気圧の傾度風は遠心力が内向き（中心向き）に加わるため、コリオリ力単独より弱い気圧傾度力で釣り合い可能で、地衡風より遅くなる。これが正しい。' },
    ],
    correctKey: 'D',
    explanation: '傾度風は、等圧線が曲がっている場合に気圧傾度力・コリオリ力・遠心力の三力がつり合って等圧線に沿って吹く風である。摩擦力は含まない点に注意する。北半球の低気圧まわりでは風は反時計回りに回り、遠心力は中心から外向き、すなわちコリオリ力と同じ側に働くため、気圧傾度力とつり合うのに必要なコリオリ力が小さくてすみ、風速は同じ気圧傾度の地衡風より小さくなる（亜地衡風的）。逆に高気圧まわりでは遠心力が気圧傾度力と同じ外向きに働くため風速は地衡風より大きくなる。この非対称が、高気圧の気圧傾度が緩やかになる理由の一つである。\n\n【図解】傾度風と地衡風の関係\n　場｜回転の向き（北半球）｜地衡風との比較\n　低気圧性｜反時計回り｜地衡風より小さい\n　高気圧性｜時計回り｜地衡風より大きい\n　直線の等圧線｜曲率なし｜地衡風に一致\n　⇒ 遠心力がコリオリ力と同じ向きか逆向きかで大小が決まる\n　⚠ 傾度風のつり合いに摩擦力を入れる選択肢は誤り。摩擦が入るのは地上風である。',
    difficulty: 'standard',
    examYear: '令和4年',
