    question: '寒冷前線の特徴として正しいものはどれか。',
    choices: [
      { key: 'A', text: '寒冷前線に伴う降水域は広く、前線の後方（西〜北西側）に長く広がる。', explanation: '寒冷前線の降水は前線帯のやや後方（西側）に集中することが多く、温暖前線のように広く前方に広がるわけではない。ただし「広く後方に」は語弊がある。' },
      { key: 'B', text: '寒冷前線は前線面の傾きが急で（約1/50〜1/100）、通過時に激しい対流性降水をもたらすことが多い。', explanation: '寒冷前線は前線面の傾きが急（約1/50〜1/100）で、寒気が暖気を強制的に持ち上げるため積乱雲が発達し、短時間の激しい降水・雷をもたらすことが多い。これが正しい。' },
      { key: 'C', text: '寒冷前線通過後、気温は上昇し、風向きは南から西に変わる。', explanation: '寒冷前線通過後は寒気が流入するため気温が低下する。風向きは南〜南西から北西〜北に急変する。' },
      { key: 'D', text: '寒冷前線は温暖前線よりも移動速度が遅い。', explanation: '寒冷前線は一般に温暖前線より移動速度が速い。このため温帯低気圧が発達する過程で寒冷前線が温暖前線に追いつき、閉塞前線が形成される。' },
    ],
    correctKey: 'B',
    explanation: '寒冷前線は重い寒気が暖気の下にもぐり込み、暖気を強制的に押し上げる前線である。前線面の傾きは約1/50〜1/100と温暖前線より急で、暖気は狭い範囲で急激に持ち上げられるため積雲・積乱雲が発達し、短時間の激しい対流性降水、雷、突風、降雹をもたらす。降水域は前線の直上からやや後方の幅数十 km程度に限られる。移動速度は温暖前線より速く、これが低気圧の発達末期に寒冷前線が温暖前線に追いついて閉塞前線を形成する理由である。通過後は気温が下がり、風向は南寄りから西〜北西寄りに急変し、気圧は上昇に転じる。\n\n【図解】寒冷前線通過時の変化\n　要素｜通過前｜通過後\n　気温｜高い｜急降下\n　風向｜南〜南西｜西〜北西\n　気圧｜下降｜上昇\n　降水｜短時間で激しい｜すみやかに止む\n　⇒ 急な前線面が狭い範囲での強い上昇流を生み、積乱雲を発達させる\n　⚠ 「通過後に気温が上昇」は温暖前線の特徴。移動速度も寒冷前線のほうが速い。',
    difficulty: 'standard',
