    question: '閉塞前線に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '閉塞前線は低気圧が最も発達した後の段階で形成され、気象的には大きな意味を持たない。', explanation: '閉塞前線は低気圧が発達期から衰退期に転じる段階で形成される。この時期でもまだ降水域が広く、気象的に重要な場合が多い。' },
      { key: 'B', text: '寒冷型閉塞前線では、前線後方の寒気が前方の寒気より温かい。', explanation: '寒冷型閉塞前線では、後方（寒冷前線側）の寒気が前方（温暖前線側）の寒気より冷たく、後方寒気が前方寒気の下に潜り込む形となる。「温かい」は逆。' },
      { key: 'C', text: '閉塞前線は寒冷前線が温暖前線に追いつくことで形成され、地上では低気圧の中心から伸びる。', explanation: '閉塞前線は寒冷前線が温暖前線に追いついて暖気が地上から切り離されることで形成され、地上では低気圧中心から延びる。これが正しい。' },
      { key: 'D', text: '温暖型閉塞前線では、前線後方の寒気が前方の寒気より冷たい。', explanation: '温暖型閉塞前線では、後方（寒冷前線側）の寒気が前方（温暖前線側）の寒気より温かい。後方寒気が前方寒気の上に乗り上げる形となる。' },
    ],
    correctKey: 'C',
    explanation: '閉塞前線は、移動の速い寒冷前線が前方の温暖前線に追いついて暖気が地上から持ち上げられ、地上では寒気同士が接する状態になった前線である。地上天気図では低気圧の中心から伸び、閉塞点より先は温暖前線と寒冷前線に分かれる。閉塞の型は、寒冷前線の後面の寒気と温暖前線の前面の寒気のどちらが冷たいかで決まる。後面の寒気のほうが冷たい場合は寒冷型閉塞前線となり寒冷前線的な振る舞いをし、後面のほうが暖かい場合は温暖型閉塞前線となって寒冷前線が温暖前線面を這い上がる。日本付近では温暖型が現れやすいとされる。\n\n【図解】閉塞前線の二つの型\n　型｜後面の寒気｜前面の寒気\n　寒冷型｜より冷たい｜相対的に暖かい\n　温暖型｜相対的に暖かい｜より冷たい\n　共通点｜暖気は地上から切離｜低気圧の最盛期\n　⇒ 閉塞の完成は低気圧が最盛期から衰弱期に向かう目安になる\n　⚠ 温暖型と寒冷型で「後面と前面のどちらが冷たいか」を入れ替える出題が定番。',
