    question: 'ポテンシャル温度（θ）に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: 'ポテンシャル温度が一定の大気層（θ = const）は乾燥断熱的な成層を示し、空気塊を置換しても元に戻らない中立状態である。', explanation: 'θ が一定の層は乾燥断熱的な成層（中立）で、空気塊を持ち上げても温度が環境と同じになり、元の位置に戻ろうとする力も落ちようとする力も働かない。これが正しい。' },
      { key: 'B', text: '対流圏では高度とともにポテンシャル温度は低下することが多い。', explanation: '大気が安定（環境減率 < 乾燥断熱減率）ならば、高度とともにポテンシャル温度は増加する。低下する場合は絶対不安定を示す。' },
      { key: 'C', text: 'ポテンシャル温度は空気塊を断熱的に1000 hPa まで移動させたときの温度で、断熱過程では保存される。', explanation: 'ポテンシャル温度 θ = T(p₀/p)^(Rd/Cp) は断熱過程（外部との熱交換がない場合）で保存される量であり、正しい定義である。' },
      { key: 'D', text: 'ポテンシャル温度は気圧に依存するため、高度が変わると大きく変化する。', explanation: 'ポテンシャル温度は断熱過程での気圧変化に対して保存される量（不変量）である。断熱的に高度が変わっても θ は変化しない。' },
    ],
    correctKey: 'A',
    explanation: '温位（ポテンシャル温度）θ は、空気塊を乾燥断熱的に基準気圧1000 hPa まで移動させたときの温度で、θ＝T(1000/p)^(R/cp) と定義される。乾燥断熱過程では保存されるため、空気塊の追跡や安定度判定に使える。鉛直分布を見ると、∂θ/∂z＞0 なら持ち上げた空気塊は周囲より低温になって戻るので安定、∂θ/∂z＝0 なら中立で置換しても元に戻ろうとせず、∂θ/∂z＜0 なら絶対不安定である。実際の対流圏は平均的に安定なので高度とともに θ は増加し、成層圏では急増する。前線帯では等温位面が大きく傾き、等温位面解析の基礎となる。\n\n【図解】温位の鉛直傾度と安定度\n　鉛直傾度｜成層｜空気塊の挙動\n　∂θ/∂z＞0｜安定｜元の高度に戻る\n　∂θ/∂z＝0｜中立｜そのまま留まる\n　∂θ/∂z＜0｜絶対不安定｜上昇を続ける\n　⇒ 対流圏では通常 θ は高度とともに増加し、成層圏で急に増加する\n　⚠ 温位は乾燥断熱過程で保存される量であり、「高度が変わると大きく変化する」は誤り。',
    difficulty: 'standard',
