    explanation: 'ラジオゾンデはゴム気球に気温・湿度・気圧のセンサーと送信機を吊るして高層大気を直接観測する測器で、上昇中の位置をGPSで追跡することにより各高度の風向・風速も得られる。到達高度はおおむね30 km前後の成層圏中部までで、熱圏には届かない。国内の定時観測は世界標準時の00 UTCと12 UTC、すなわち日本時間の9時と21時の1日2回が基本である。得られた鉛直プロファイルは数値予報の初期値を作るデータ同化にとって最重要級の直接観測であり、エマグラム解析による安定度評価にも用いられる。近年は航空機観測やGNSS掩蔽観測が補完的に加わっている。\n\n【図解】ラジオゾンデ観測の基本\n　項目｜内容｜補足\n　観測要素｜気温・湿度・気圧｜GPSで風も算出\n　観測時刻｜00と12 UTC｜日本時間の9時と21時\n　到達高度｜約30 km前後｜成層圏中部まで\n　用途｜初期値作成と安定度解析｜エマグラムに描画\n　⇒ 高層の直接観測はデータ同化における基準データとして今も不可欠である\n　⚠ 「1日4回」「熱圏まで観測」は誤り。定時は1日2回、到達は成層圏までである。',
