    explanation: '降水確率予報は、対象地域・対象時間帯（3時間ないし6時間）内に1 mm以上の降水がある確率を、0〜100 %の10 %刻みで発表するものである。値は面積の割合でも降水量の多寡でもなく、あくまで発現の確率を示す。したがって降水確率60 %のほうが40 %より雨量が多いとは限らず、降水確率が低くても短時間強雨が起こることはある。0 %は端数処理で5 %未満を丸めた表示であり、降水が絶対に無いことを保証しない。基準が1 mm以上であるため、0.1 mm程度のごく弱い霧雨だけの場合は降水確率の対象に含まれない点も押さえておきたい。\n\n【図解】降水確率予報の定義\n　項目｜内容｜注意点\n　しきい値｜1 mm以上の降水｜霧雨程度は対象外\n　刻み｜10 %刻み｜0〜100 %\n　意味｜発現の確率｜面積比でも雨量でもない\n　0 %の意味｜5 %未満を丸めた値｜降水皆無の保証ではない\n　⇒ 確率の大小と予想降水量の大小は別物として扱う\n　⚠ 「30 %は地域の30 %の面積で降る」は典型的な誤解。確率と面積割合は無関係。',
