    choices: [
      { key: 'A', text: '梅雨前線は熱帯収束帯（ITCZ）が北上したものであり、強い太陽加熱のみが降水の主要因である。', explanation: '梅雨前線はオホーツク海高気圧などの冷涼な気団と太平洋高気圧の暖湿な気団の境界に形成され、ITCZ が直接北上したものではない。また降水には水蒸気収束や上昇流なども重要。' },
      { key: 'B', text: '梅雨期の集中豪雨は、下層の暖湿な南西風による水蒸気輸送、前線帯の水蒸気収束、条件付き不安定による対流の発達が組み合わさって生じる。', explanation: '梅雨期の集中豪雨は、①下層ジェット（LLJ）による暖湿気の輸送、②前線帯での収束・強制上昇、③対流不安定（CAPE）の解放が連動して発生する。これが正しい総合的な記述。' },
      { key: 'C', text: '梅雨前線は冬季の日本海に発生し、冬型気圧配置のときに活発化する。', explanation: '梅雨前線は初夏（5〜7 月）に日本付近に停滞する前線。冬季の日本海の降雪・降雨は日本海側の雪雲（シアーライン）によるものであり、梅雨前線とは異なる。' },
      { key: 'D', text: '梅雨前線に伴う降水は全て層状性降水であり、対流性降水は含まれない。', explanation: '梅雨期の降水は層状性と対流性の両方を含む。特に集中豪雨では組織化されたメソ対流系（MCS）による強い対流性降水が卓越する。' },
    ],
    correctKey: 'B',
    explanation: '梅雨前線はオホーツク海高気圧などの冷涼な気団と太平洋高気圧の暖湿な気団の間にできる停滞前線で、南北の温度差より水蒸気量の差、すなわち相当温位の傾度が大きいことが特徴である。集中豪雨は、下層ジェットによる南西からの大量の水蒸気輸送、前線帯での水蒸気収束、条件付き不安定の解放という三つが重なったときに起こる。持続的な暖湿気の流入と地形や局地前線による持ち上げが続くと、積乱雲が次々と同じ場所で発生・発達するバックビルディング型の線状降水帯が形成され、同一地域に長時間の強雨をもたらす。降水は層状性と対流性が混在する。\n\n【図解】梅雨期の豪雨をつくる要素\n　要素｜内容｜役割\n　下層ジェット｜南西風の水蒸気輸送｜暖湿気の供給\n　前線帯の収束｜相当温位集中帯｜上昇流の強制\n　条件付き不安定｜Γm＜Γe＜Γd｜対流の発達\n　⇒ 三つがそろって積乱雲が連続発生すると線状降水帯になる\n　⚠ 梅雨前線を熱帯収束帯の北上と説明するのは誤り。異なる気団の境界にできる停滞前線である。',
