    question: '大気の質量保存則（連続の式）に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '連続の式は運動量保存則の別名であり、質量保存とは無関係である。', explanation: '誤り。連続の式は質量保存則を表す方程式であり、運動量保存則（運動方程式）とは異なる独立した基礎方程式である。' },
      { key: 'B', text: '連続の式は大気の質量が保存されることを表し、非圧縮性近似では水平発散と鉛直流の変化率が釣り合う関係が成立する。', explanation: '正しい。連続の式（質量保存則）は大気の質量が生成・消滅しないことを表す。非圧縮性近似（ブジネスク近似）では水平発散 ∂u/∂x + ∂v/∂y と鉛直流の高度変化 ∂w/∂z が打ち消し合う関係になる。' },
      { key: 'C', text: '連続の式によれば、大気中のある領域で質量が増加する場合、その領域の境界を通じた質量の流入は起こりえない。', explanation: '誤り。連続の式はまさに、境界を通じた質量の正味の流入（収束）があれば領域内の質量（密度）が増加することを表す式であり、記述はこれと矛盾する。' },
      { key: 'D', text: '連続の式は水平方向の運動にのみ適用され、鉛直方向の運動には適用されない。', explanation: '誤り。連続の式は三次元的な質量保存を表す式であり、水平方向（発散）と鉛直方向（鉛直流の変化）の両方を含む。' },
    ],
    correctKey: 'B',
    explanation: '連続の式（質量保存則）は大気中で質量が保存されることを表す基礎方程式。非圧縮性近似では水平発散と鉛直流の高度変化が釣り合う（∂u/∂x+∂v/∂y+∂w/∂z=0）。水平収束があれば鉛直流（上昇流）が生じる関係を導く重要な式である。\n【図解】\n　A: 連続の式は運動量保存則の別名であり、質量保存とは無関係である。\n★B: 連続の式は大気の質量が保存されることを表し、非圧縮性近似では水平発散と鉛直流の変化率…\n　C: 連続の式によれば、大気中のある領域で質量が増加する場合、その領域の境界を通じた質量の…\n　D: 連続の式は水平方向の運動にのみ適用され、鉛直方向の運動には適用されない。\n→ ★が正解（B）',
