    question: '傾度風の力学的な性質に関する記述として正しいものはどれか。',
    choices: [
      { key: 'A', text: '低気圧性の傾度風（気圧傾度力・コリオリ力・遠心力がつり合う流れ）では、理論上いくらでも大きな風速の解が存在しうる。', explanation: '誤り。低気圧性の傾度風の風速には理論的な上限（Vmax ＝ fr/2、fはコリオリパラメータ、rは曲率半径）があり、これを超える気圧傾度に対しては傾度風の解が実数として存在しなくなる（超傾度風の状態となり、実際には非定常な加速や不安定が生じる）。' },
      { key: 'B', text: '高気圧性の傾度風では、気圧傾度力が大きくなりすぎると解が実数として存在しなくなるため、高気圧の中心付近の気圧傾度は低気圧に比べて緩やかになりやすい。', explanation: '正しい。高気圧性循環の傾度風の風速方程式を解くと、判別式の関係から気圧傾度力に上限が存在し、これを超えると実数解が得られない。このため高気圧の中心付近では急激な等圧線の混み合い（強い気圧傾度）が生じにくく、低気圧に比べて中心付近の等圧線間隔が緩やかになる傾向がある。' },
      { key: 'C', text: '傾度風の風速は、同じ気圧傾度・同じ曲率半径であれば、低気圧性循環と高気圧性循環とで常に等しい値になる。', explanation: '誤り。同じ気圧傾度・曲率半径であっても、遠心力の向き（低気圧では外向き、高気圧では内向き）が異なるため、低気圧性の傾度風は地衡風より弱く、高気圧性の傾度風は地衡風より強くなり、両者は一致しない。' },
      { key: 'D', text: '傾度風は摩擦力を含めた四力のつり合いで定義される風であり、地表付近の観測風とほぼ一致する。', explanation: '誤り。傾度風は気圧傾度力・コリオリ力・遠心力の三力のつり合いで定義される風で、摩擦力は含まれない。摩擦を含む地表付近の実際の風とは異なり、傾度風はおおむね自由大気（摩擦層より上）で近似される風である。' },
    ],
    correctKey: 'B',
    explanation: '傾度風の風速方程式には判別式が実数解を持つための条件があり、高気圧性循環では気圧傾度力に上限が存在する（超傾度は生じにくい）。このため高気圧の中心気圧勾配は低気圧に比べ緩やかになりやすい。低気圧性循環では風速の上限（Vmax＝fr/2）が存在する。\n【図解】\n★ポイント: 傾度風の解は判別式条件に制約され、高気圧側では気圧傾度力に上限が存在する\n○正: Bの通り、高気圧中心付近の等圧線は低気圧に比べて混み合いにくい（気圧傾度が緩やか）\n×誤: Aのように低気圧性傾度風の風速が無制限に大きくなるという記述、Cのように低・高気圧で傾度風速が等しいとする記述はいずれも力学的に誤り\n→ 結論: 判別式条件と高気圧の等圧線構造を正しく説明したBが正解（B）',
