    question: '大気の安定度を診断する指数（SSI：ショワルター安定指数、K指数など）に関する記述として誤っているものはどれか。',
    choices: [
      { key: 'A', text: 'ショワルター安定指数（SSI）は850 hPaの空気塊を断熱的に500 hPaまで持ち上げたときの気温と、その高度の実際の気温との差で定義され、値が小さい（負に大きい）ほど大気は不安定とされる。', explanation: '正しい記述である。SSI ＝（500 hPaの実際の気温）－（850 hPaの空気塊を断熱的に持ち上げた際の500 hPaでの気温）で定義され、負に大きいほど強い不安定を示す指標として実技試験でも用いられる。' },
      { key: 'B', text: 'K指数は気温減率・下層の湿数（気温と露点温度の差）・中層の湿り具合を組み合わせた指数で、値が大きいほど雷雨（対流性降水）の可能性が高いとされる。', explanation: '正しい記述である。K指数は850hPaと500hPaの気温差、850hPaの露点、700hPaの湿数を組み合わせた経験式で算出され、値が大きいほど大気中の水蒸気量と不安定度が高く、雷雨発生の可能性が高いことを示す。' },
      { key: 'C', text: 'SSIやK指数などの安定度指数は、CAPEと同様にエマグラムの情報から算出される診断量であり、いずれも数値予報の初期時刻以外（任意の予報時刻）についても算出できる。', explanation: '正しい記述である。安定度指数は特定の等圧面（850hPa、700hPa、500hPaなど）の気温・湿度から算出されるため、数値予報の各予報時刻の格子点データからも計算可能であり、実況監視だけでなく予測資料としても利用される。' },
      { key: 'D', text: '安定度指数（SSIやK指数）が不安定を示す値であれば、その地点で必ず積乱雲が発生し雷雨となる。', explanation: '不適当。安定度指数はあくまで大気の潜在的な不安定性を示す指標であり、実際に対流（積乱雲）が発生するには、CIN（対流抑制）を超える持ち上げ力（トリガー）が必要である。指数が不安定を示していても、トリガーがなければ対流は発生しないことがある。' },
    ],
    correctKey: 'D',
    explanation: 'SSI・K指数は大気の潜在的不安定度を診断する指標で、エマグラムの気温・露点情報から850・700・500hPaなどの値を組み合わせて算出される。ただし指数が不安定を示しても、実際の対流発生にはCINを超える上昇のきっかけ（地形・前線・日射など）が必要であり、指数だけで発雷を断定できない点に注意が必要。\n【図解】\n★ポイント: 安定度指数は「潜在的な不安定さ」の指標であり、対流発生の確実な予告ではない\n○正: A・B・Cはいずれも指数の定義・算出方法として正確な記述\n×誤: Dは指数が不安定でも必ず積乱雲・雷雨になるとしている点が誤り。CIN（対流抑制）を超えるトリガーが別途必要\n⚠注意: 実技試験ではSSI・K指数と地上・上空の収束、日射加熱などのトリガーを総合的に見る視点が問われる\n→ 結論: 指数と実際の発雷を短絡的に結びつけたDが誤りであり正解（D）',
