    explanation: 'オゾン層は成層圏に存在し有害紫外線を吸収する。フロン類による塩素の触媒反応がオゾン層破壊の主因で、南極オゾンホールは南半球の春に顕著化する季節現象。モントリオール議定書の効果で回復傾向にはあるが、まだ消滅はしておらず毎年観測されている。\n【図解】\n★ポイント: オゾンホールは規制により「回復傾向」だが「完全消滅」はまだしていない（今世紀半ば以降に本格回復の見込み）\n○正: A・B・Cはオゾン層の役割・南極オゾンホールの季節性・フロンによる破壊機構をいずれも正確に説明\n×誤: Dの「既に完全に消滅した」は事実に反する誤った記述\n→ 結論: 回復途上の状況を「完全消滅」と誤って述べたDが正解（D）',
