    choices: [
      { key: 'A', text: '放射強制力は大気上端でのエネルギー収支のみに関する概念であり、地表面の気温変化とは無関係な指標である。', explanation: '誤り。放射強制力は温暖化・寒冷化の駆動力となる量であり、正味の放射強制力が正であれば地球システムにエネルギーが蓄積され、最終的に地表・大気の平均気温上昇（気候感度に応じた昇温）につながる、気候変化の予測に直結する指標である。' },
      { key: 'B', text: '二酸化炭素による放射強制力は、大気中濃度の増加量に正比例して直線的に増大する。', explanation: '誤り。二酸化炭素の放射強制力は濃度の対数にほぼ比例する関係にあることが知られており、濃度が低いうちは追加分の効果が大きく、濃度が高くなるほど追加分の効果（限界的な放射強制力）は小さくなる（飽和的な性質を持つ）。' },
      { key: 'C', text: '放射強制力が正の値をとる要因（温室効果ガスなど）と負の値をとる要因（エーロゾルの直接効果など）は、地球全体のエネルギー収支への影響としてはどちらも同じ方向（温暖化）に働く。', explanation: '誤り。正の放射強制力は地球システムへの正味エネルギー流入を増加させ温暖化方向に働くのに対し、負の放射強制力（硫酸エーロゾルによる太陽光散乱など）はエネルギー流入を減少させ冷却方向に働く。両者は逆方向の効果を持つ。' },
      { key: 'D', text: '放射強制力とは、ある要因（温室効果ガスの増加など）によって地球のエネルギー収支（大気上端における入射・射出エネルギーの差）がどれだけ変化するかを表す量で、単位はW/m²である。', explanation: '正しい。放射強制力（RF: Radiative Forcing）は、産業革命前などの基準状態と比較して、ある要因が対流圏界面（または大気上端）での正味放射フラックスをどれだけ変化させるかを定量化した量で、単位はW/m²として表される。値が正であれば地球システムを温暖化させる方向に働く。' },
    ],
    correctKey: 'D',
    explanation: '放射強制力（W/m²）は大気上端でのエネルギー収支の変化を定量化した指標で、正の値は温暖化、負の値は冷却方向に働く。CO₂の放射強制力は濃度の対数にほぼ比例し、追加濃度あたりの効果は徐々に小さくなる（対数則）。\n【図解】\n★ポイント: 放射強制力の単位はW/m²。CO₂の効果は濃度の「対数」に比例（直線ではない＝飽和的）\n○正: Dの通り、放射強制力は大気上端のエネルギー収支の変化を定量化した指標である\n×誤: Bのように濃度に正比例（直線的）とする記述、Cのように正・負の強制力が同じ方向に働くとする記述、Aのように地表気温と無関係とする記述はいずれも誤り\n→ 結論: 定義と対数則の性質を正確に述べたDが正解（D）',
