    explanation: '地衡風調節過程は、バランスの崩れた場が慣性重力波の放射を通じて地衡風平衡に近づく過程。特徴的スケールはロスビー変形半径 Lr＝c/f で、緯度（コリオリパラメータ）に応じて変化する。コリオリ力が強い高緯度ほど調節は速く進み、赤道付近では働きにくい。\n【図解】\n★ポイント: ロスビー変形半径 Lr ＝ c/f が「気圧場・風速場どちらが主に調整されるか」を決める鍵で、緯度により変化する\n○正: Aの通り、地衡風調節過程は慣性重力波の放射を介した平衡化の過程である\n×誤: Bのように風速場のみが一方的に調整されるとする記述、Cのようにロスビー変形半径を地球半径と同一視する記述、Dのように赤道域で最も速く進行するとする記述はいずれも誤り\n→ 結論: 過程の本質を正しく捉えたAが正解（A）',
