    choices: [
      { key: 'A', text: '台風の「強さ」の階級（強い・非常に強い・猛烈な）は中心付近の最大風速に基づいて区分され、「大きさ」の階級（大型・超大型）は風速15 m/s以上の強風域の半径に基づいて区分される。', explanation: '正しい。気象庁の台風の階級表現では、「強さ」は最大風速（強い：33 m/s以上44 m/s未満、非常に強い：44 m/s以上54 m/s未満、猛烈な：54 m/s以上）で区分され、「大きさ」は風速15 m/s以上の強風域の半径（大型＝500 km以上800 km未満、超大型＝800 km以上）で区分される、独立した2つの尺度である。' },
      { key: 'B', text: '台風の「強さ」の階級は中心気圧のみによって決定され、風速は考慮されない。', explanation: '誤り。台風の「強さ」の階級は中心付近の最大風速によって区分されるものであり、中心気圧そのものを基準とした階級分けではない（中心気圧は勢力の参考値としては用いられるが、階級区分の直接基準ではない）。' },
      { key: 'C', text: '「大型」の台風は必ず「強い」台風以上の勢力を持つ。', explanation: '誤り。「大きさ」（強風域の広がり）と「強さ」（最大風速）は独立した別の尺度であり、大型であっても勢力（強さ）が弱い台風、逆に小型でも猛烈な強さの台風もありうる。両者は必ずしも連動しない。' },
      { key: 'D', text: '台風の階級表現における「非常に強い」は、最大風速が25 m/s以上33 m/s未満の場合に用いられる。', explanation: '誤り。最大風速25 m/s以上33 m/s未満は「強い」未満の階級（無印、いわゆる「台風」の基本階級）に相当し、「非常に強い」は最大風速44 m/s以上54 m/s未満の場合に用いられる階級である。' },
    ],
    correctKey: 'A',
    explanation: '気象庁の台風階級表現では「強さ」（最大風速：強い33〜44m/s未満、非常に強い44〜54m/s未満、猛烈な54m/s以上）と「大きさ」（強風域半径：大型500〜800km未満、超大型800km以上）は独立した2つの尺度で表現され、両者は必ずしも連動しない。\n【図解】\n★ポイント: 「強さ」＝最大風速の階級、「大きさ」＝強風域（15m/s以上）半径の階級、この2軸は独立\n○正: Aの通り、強さと大きさはそれぞれ別の基準（風速・半径）で決まる独立した尺度である\n×誤: Bのように中心気圧のみで強さが決まるとする記述、Cのように大型なら必ず強いとする記述、Dのように非常に強いを25〜33m/sとする記述はいずれも誤り\n→ 結論: 強さ・大きさの定義と独立性を正確に述べたAが正解（A）',
