    correctKey: 'A',
    explanation: 'CAPE（発達ポテンシャル）・CIN（対流抑制）・SSIやK指数（簡便な安定度指標）はそれぞれ異なる側面を表す診断量であり、これらを組み合わせて対流発生の可能性と激しさを総合的に評価することが実技試験・実際の予報業務双方で重要となる。CAPE大・CIN小は弱いトリガーでも発雷しやすい状態、CAPE大・CIN大はエネルギー蓄積後の急発達（時に猛烈な現象）に注意すべき状態を示す。\n【図解】\n★ポイント: CAPE（発達の激しさ）とCIN（起こりやすさへの抑制）は別々の意味を持つ指標として組み合わせて読む\n○正: Aの通り、CAPE大・CIN小の組み合わせは弱いトリガーでも発雷しやすい状態を示す\n×誤: BはCINが対流発生に影響しないとする点、CはCAPE大・CIN大の状態を警戒不要とする点、DはCAPE・CIN・安定度指数が同じ情報の言い換えに過ぎないとする点でいずれも誤り\n⚠注意: CAPE大・CIN大の状態は「静けさの中の危険」であり、キャップ崩壊後の急発達（竜巻・スーパーセル）への警戒が実技上のポイント\n→ 結論: CAPE・CINの意味と組み合わせパターンを的確に説明したAが最も適当であり正解（A）',
